<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
require __DIR__.'/../app/admin_shell.php';
security_headers();require_admin();
$db=database();$state=admin_activity_resolution($db);$activity=$state['activity'];if(!$activity){header('Location: /admin/activities.php');exit;}$activityId=(int)$activity['id'];
$courseId=max(0,(int)($_GET['course']??$_POST['course_id']??0));$course=$courseId>0?course_by_id($db,$courseId):null;if($course&&(int)$course['activity_id']!==$activityId){$course=null;$courseId=0;}
$view=(string)($_GET['view']??'overview');if(in_array($view,['cohorts','students','lessons','material'],true)&&$course){header('Location: '.admin_course_url($activityId,$courseId,$view),true,302);exit;}if(!in_array($view,['overview','setup'],true))$view='overview';
$q=trim((string)($_GET['q']??$_POST['return_q']??''));$page=max(1,(int)($_GET['page']??$_POST['return_page']??1));$pageSize=25;
function course_catalog_url(int $activityId,int $courseId=0,string $view='overview',string $q='',int $page=1): string {$args=['activity'=>$activityId];if($courseId>0)$args['course']=$courseId;if($view==='setup')$args['view']='setup';if($q!=='')$args['q']=$q;if($page>1)$args['page']=$page;return '/admin/courses.php?'.http_build_query($args);}
$pageOptions=[];$formOptions=[];if(!$course||$view==='setup'){$pageOptions=array_values(array_filter(cms_pages($db,$activityId,null,true),static fn(array $p): bool=>(string)$p['status']!=='archived'));$formOptions=array_values(array_filter(cms_forms($db,$activityId),static fn(array $f): bool=>cms_form_purpose($f)==='enrollment'&&(string)($f['status']??'')!=='archived'));}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('courses-admin',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}$action=(string)($_POST['action']??'');
    try{
        if($action==='create_from_page'){$created=course_create_from_page($db,(int)($_POST['public_page_id']??0),(int)($_POST['registration_form_id']??0));$courseId=(int)$created['id'];$course=$created;$view='overview';}
        elseif($action==='update_course'&&$course){$course=course_update($db,$courseId,$_POST);$view='setup';}
        else throw new RuntimeException('Ação inválida.');
        $_SESSION['admin_courses_notice']='Alteração salva.';
    }catch(Throwable $e){$_SESSION['admin_courses_notice']='Não foi possível concluir: '.$e->getMessage();}
    header('Location: '.course_catalog_url($activityId,$courseId,$view,$q,$page),true,303);exit;
}
$notice=(string)($_SESSION['admin_courses_notice']??'');unset($_SESSION['admin_courses_notice']);$noticeTone=str_starts_with($notice,'Não foi possível')?'error':'success';
admin_shell_start('courses','Cursos',$state,['/assets/admin-teaching.css']);?>
<?php if($notice!==''):?><div class="admin-notice <?=h($noticeTone)?>" role="<?=$noticeTone==='error'?'alert':'status'?>"><?=h($notice)?></div><?php endif;?>
<?php if(!$course):
$where=["c.activity_id=?","c.status!='archived'"];$args=[$activityId];if($q!==''){$where[]='(c.title LIKE ? OR c.slug LIKE ? OR p.title LIKE ? OR f.title LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like,$like);}$whereSql=implode(' AND ',$where);
$count=$db->prepare("SELECT COUNT(*) FROM courses c LEFT JOIN cms_pages p ON p.id=c.public_page_id LEFT JOIN cms_forms f ON f.id=c.registration_form_id WHERE $whereSql");$count->execute($args);$total=(int)$count->fetchColumn();$pagesCount=max(1,(int)ceil($total/$pageSize));if($page>$pagesCount)$page=$pagesCount;$offset=($page-1)*$pageSize;
$sql="SELECT c.*,p.title public_page_title,p.status public_page_status,f.title registration_form_title,f.status registration_form_status,(SELECT COUNT(*) FROM course_cohorts cc WHERE cc.course_id=c.id AND cc.status!='archived') cohorts,(SELECT COUNT(*) FROM course_enrollments e JOIN course_cohorts cc ON cc.id=e.cohort_id WHERE cc.course_id=c.id AND cc.status!='archived' AND e.status='active') students,(SELECT COUNT(*) FROM course_lessons l WHERE l.course_id=c.id) lessons,(SELECT COUNT(*) FROM course_material_pages m WHERE m.course_id=c.id) material,(SELECT COUNT(*) FROM cms_form_submissions s WHERE s.course_id=c.id AND s.status!='archived') registrations,(SELECT COUNT(*) FROM cms_form_submissions s WHERE s.course_id=c.id AND s.status!='archived' AND (s.payment_status='paid' OR s.status='converted') AND s.cohort_id IS NULL) unassigned FROM courses c LEFT JOIN cms_pages p ON p.id=c.public_page_id LEFT JOIN cms_forms f ON f.id=c.registration_form_id WHERE $whereSql ORDER BY c.title COLLATE NOCASE,c.id LIMIT $pageSize OFFSET $offset";$stmt=$db->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll();?>
<form class="admin-data-toolbar" method="get"><input type="hidden" name="activity" value="<?=$activityId?>"><label class="grow">Buscar curso<input name="q" value="<?=h($q)?>" placeholder="Nome, slug, página pública ou formulário"></label><div class="admin-inline-actions"><button class="admin-button" type="submit">Buscar</button><?php if($q!==''):?><a class="admin-button secondary" href="<?=h(course_catalog_url($activityId))?>">Limpar</a><?php endif;?></div></form>
<?php if($q!==''):?><div class="admin-active-filters" aria-label="Filtros ativos"><span>Filtros ativos</span><?=admin_filter_chip('Busca',$q,course_catalog_url($activityId))?></div><?php endif;?>
<div class="admin-list-summary"><span><?php if($total>0):?>Mostrando <?=($offset+1)?>–<?=min($offset+$pageSize,$total)?> de <?=$total?> curso(s)<?php else:?>Nenhum curso encontrado<?php endif;?></span><span>Curso é catálogo; inscrições, turmas, alunos, aulas e material continuam em coleções próprias.</span></div>
<?php if(!$rows):?><div class="admin-empty">Nenhum curso configurado.</div><?php else:?><div class="admin-table-scroll" tabindex="0" role="region" aria-label="Lista de cursos"><table class="admin-data-table"><thead><tr><th>Curso</th><th>Publicação</th><th>Operação</th><th>Ensino</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><div class="admin-table-primary"><strong><?=h((string)$row['title'])?></strong><span><?=h((string)$row['slug'])?></span></div><div class="admin-teaching-meta"><?=admin_badge(admin_status_label('course',(string)$row['status']),admin_status_tone('course',(string)$row['status']))?></div></td><td><div class="admin-relation-stack"><strong><?=h((string)($row['public_page_title']?:'Sem página pública'))?></strong><?php if($row['public_page_title']):?><span><?=admin_badge(admin_status_label('page',(string)$row['public_page_status']),admin_status_tone('page',(string)$row['public_page_status']))?></span><?php endif;?><span><?=h((string)($row['registration_form_title']?:'Sem formulário de inscrição'))?></span></div></td><td><div class="admin-table-compact-counts"><span><strong><?=(int)$row['registrations']?></strong> inscrições</span><span><strong><?=(int)$row['cohorts']?></strong> turmas</span><span><strong><?=(int)$row['students']?></strong> alunos</span></div><?php if((int)$row['unassigned']>0):?><div class="muted"><?=(int)$row['unassigned']?> confirmada(s) sem turma</div><?php endif;?></td><td><div class="admin-table-compact-counts"><span><strong><?=(int)$row['lessons']?></strong> aulas</span><span><strong><?=(int)$row['material']?></strong> páginas</span></div></td><td class="actions"><a class="admin-button secondary admin-table-action" href="<?=h(course_catalog_url($activityId,(int)$row['id'],'overview',$q,$page))?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<div class="admin-pagination"><span>Página <?=$page?> de <?=$pagesCount?></span><?php if($pagesCount>1):?><nav aria-label="Paginação de cursos"><?php if($page>1):?><a href="<?=h(course_catalog_url($activityId,0,'overview',$q,$page-1))?>">← Anterior</a><?php endif;?><?php if($page<$pagesCount):?><a href="<?=h(course_catalog_url($activityId,0,'overview',$q,$page+1))?>">Próxima →</a><?php endif;?></nav><?php endif;?></div>
<div class="admin-teaching-create"><details class="admin-secondary-setup"><summary class="admin-button secondary">Associar página a novo curso</summary><section class="admin-card"><header><div><h2>Novo curso</h2><p>O curso nasce da relação com uma página pública existente. O formulário de inscrição pode ser associado agora ou depois.</p></div></header><form class="admin-form-grid" method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('courses-admin'))?>"><input type="hidden" name="action" value="create_from_page"><input type="hidden" name="return_q" value="<?=h($q)?>"><input type="hidden" name="return_page" value="<?=$page?>"><label class="admin-form-span-2">Página pública<select name="public_page_id" required><option value="">Escolha uma página</option><?php foreach($pageOptions as $item):if(course_by_public_page($db,(int)$item['id']))continue;?><option value="<?=(int)$item['id']?>"><?=h((string)$item['title'].' · '.public_language_label((string)$item['locale']))?></option><?php endforeach;?></select></label><label class="admin-form-span-2">Formulário de inscrição<select name="registration_form_id"><option value="0">Associar depois</option><?php foreach($formOptions as $item):?><option value="<?=(int)$item['id']?>"><?=h((string)$item['title'].' · '.public_language_label((string)$item['locale']))?></option><?php endforeach;?></select></label><div class="admin-form-actions"><button class="admin-button" type="submit">Associar curso</button></div></form></section></details></div>
<?php else:
$statsQ=$db->prepare("SELECT (SELECT COUNT(*) FROM course_cohorts WHERE course_id=? AND status!='archived') cohorts,(SELECT COUNT(*) FROM course_enrollments e JOIN course_cohorts c ON c.id=e.cohort_id WHERE c.course_id=? AND e.status='active') students,(SELECT COUNT(*) FROM course_lessons WHERE course_id=?) lessons,(SELECT COUNT(*) FROM course_material_pages WHERE course_id=?) material,(SELECT COUNT(*) FROM cms_form_submissions WHERE course_id=? AND status!='archived') registrations,(SELECT COUNT(*) FROM cms_form_submissions WHERE course_id=? AND status!='archived' AND (payment_status='paid' OR status='converted') AND cohort_id IS NULL) unassigned,(SELECT COUNT(*) FROM student_questions sq JOIN course_cohorts sc ON sc.id=sq.cohort_id WHERE sc.course_id=? AND sq.status='open') questions");$statsQ->execute([$courseId,$courseId,$courseId,$courseId,$courseId,$courseId,$courseId]);$stats=$statsQ->fetch()?:[];
