<section class="admin-card admin-teaching-detail"><header><div><a class="admin-back" href="<?=h(course_catalog_url($activityId,0,'overview',$q,$page))?>">← Cursos</a><p class="admin-kicker">Curso</p><h2><?=h((string)$course['title'])?></h2><div class="admin-teaching-meta"><?=admin_badge(admin_status_label('course',(string)$course['status']),admin_status_tone('course',(string)$course['status']))?><span><?=h((string)$course['slug'])?></span><?php if($publicPage):?><span>Página: <?=h((string)$publicPage['title'])?></span><?php endif;?><?php if($registrationForm):?><span>Formulário: <?=h((string)$registrationForm['title'])?></span><?php endif;?></div></div><div class="admin-card-actions"><?php if($view!=='setup'):?><a class="admin-button secondary" href="<?=h(course_catalog_url($activityId,$courseId,'setup',$q,$page))?>">Configurar</a><a class="admin-button secondary" href="/admin/questions.php?<?=h(http_build_query(['activity'=>$activityId,'course'=>$courseId]))?>">Dúvidas<?=(int)($stats['questions']??0)>0?' · '.(int)$stats['questions']:''?></a><?php else:?><a class="admin-button secondary" href="<?=h(course_catalog_url($activityId,$courseId,'overview',$q,$page))?>">Visão geral</a><?php endif;?><?php if($publicPage):?><a class="admin-button secondary" href="/editor/?page=<?=(int)$publicPage['id']?>">Editar página</a><?php endif;?></div></header></section>
<?php if($view==='setup'):$course=course_by_id($db,$courseId)??$course;?>
<section class="admin-card"><header><div><h2>Configuração</h2><p>Página pública e formulário são objetos globais do CMS. Esta tela administra apenas a relação deles com o curso.</p></div></header><form class="admin-form-grid" method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('courses-admin'))?>"><input type="hidden" name="action" value="update_course"><input type="hidden" name="course_id" value="<?=$courseId?>"><input type="hidden" name="return_q" value="<?=h($q)?>"><input type="hidden" name="return_page" value="<?=$page?>"><label class="admin-form-span-2">Nome do curso<input name="title" value="<?=h((string)$course['title'])?>" required></label><label>Slug<input name="slug" value="<?=h((string)$course['slug'])?>" required></label><label>Página pública<select name="public_page_id" required><?php foreach($pageOptions as $item):$owner=course_by_public_page($db,(int)$item['id']);if($owner&&(int)$owner['id']!==$courseId)continue;?><option value="<?=(int)$item['id']?>"<?=(int)$course['public_page_id']===(int)$item['id']?' selected':''?>><?=h((string)$item['title'].' · '.admin_status_label('page',(string)$item['status']))?></option><?php endforeach;?></select></label><label class="admin-form-span-2">Formulário de inscrição<select name="registration_form_id"><option value="0">Nenhum</option><?php foreach($formOptions as $item):?><option value="<?=(int)$item['id']?>"<?=(int)($course['registration_form_id']??0)===(int)$item['id']?' selected':''?>><?=h((string)$item['title'])?></option><?php endforeach;?></select></label><div class="admin-form-actions"><button class="admin-button" type="submit">Salvar configuração</button><?php if($registrationForm):?><a class="admin-button secondary" href="/admin/forms.php?activity=<?=$activityId?>&form=<?=(int)$registrationForm['id']?>">Editar formulário</a><?php endif;?></div></form></section>
<?php else:?>
